"""SQL generated by `build_filter` for the text matching operators."""

import pytest

from ayon_server.sqlfilter import (
    QueryCondition,
    QueryFilter,
    build_condition,
    build_filter,
)


def test_like_on_attribute():
    condition = QueryCondition(key="attrib.note", operator="like", value="%foo%")
    assert build_condition(condition) == "(attrib->>'note') ILIKE '%foo%'"


def test_notlike_on_attribute_keeps_missing_values():
    condition = QueryCondition(key="attrib.note", operator="notlike", value="%foo%")
    assert (
        build_condition(condition)
        == "NOT coalesce((attrib->>'note') ILIKE '%foo%', FALSE)"
    )


def test_notlike_on_column():
    condition = QueryCondition(key="name", operator="notlike", value="%foo%")
    assert (
        build_condition(condition, table_prefix="tasks")
        == "NOT coalesce((tasks.name) ILIKE '%foo%', FALSE)"
    )


@pytest.mark.parametrize("operator", ["notlike", "not_like", "NOT-LIKE", "NotLike"])
def test_notlike_operator_spelling(operator: str):
    condition = QueryCondition(key="attrib.note", operator=operator, value="%a%")
    assert condition.operator == "notlike"


def test_notlike_escapes_quotes():
    condition = QueryCondition(key="attrib.note", operator="notlike", value="%it's%")
    assert "ILIKE '%it''s%'" in build_condition(condition)


def test_notlike_requires_string_value():
    condition = QueryCondition(key="attrib.note", operator="notlike", value=1)
    with pytest.raises(ValueError):
        build_condition(condition)


def test_notlike_conditions_in_filter():
    f = QueryFilter(
        operator="and",
        conditions=[
            QueryCondition(key="attrib.note", operator="notlike", value="%a%"),
            QueryCondition(key="attrib.note", operator="notlike", value="%b%"),
        ],
    )
    assert build_filter(f) == (
        "(NOT coalesce((attrib->>'note') ILIKE '%a%', FALSE)"
        " AND NOT coalesce((attrib->>'note') ILIKE '%b%', FALSE))"
    )


def test_description_matching_resolves_only_description():
    from ayon_server.graphql.resolvers.common import get_resolved_attrib_expression

    condition = QueryCondition(
        key="attrib.description", operator="like", value="%world%"
    )
    result = build_condition(
        condition,
        table_prefix="tasks",
        column_map={
            "attrib": get_resolved_attrib_expression(
                "task", "tasks.attrib", inherited="f_ex.attrib"
            )
        },
    )
    assert result == (
        "((NULLIF((tasks.attrib)->'description', 'null'::jsonb)) #>> '{}') "
        "ILIKE '%world%'"
    )
    assert "f_ex.attrib" not in result
    assert "jsonb_object_agg" not in result


def test_inherited_text_matching_does_not_change_coalesce_operands():
    from ayon_server.graphql.resolvers.common import get_resolved_attrib_expression

    expression = get_resolved_attrib_expression(
        "task", "tasks.attrib", inherited="f_ex.attrib"
    )
    condition = QueryCondition(key="attrib.fps", operator="like", value="%25%")
    result = build_condition(condition, column_map={"attrib": expression})
    assert result == f"(({expression('fps')}) #>> '{{}}') ILIKE '%25%'"
    assert "->>" not in result


def test_nested_callable_attribute_mapping():
    calls = []

    def resolve(name):
        calls.append(name)
        return "resolved_value"

    result = build_condition(
        QueryCondition(key="attrib.payload.nested", operator="eq", value="world"),
        column_map={"attrib": resolve},
    )
    assert calls == ["payload"]
    assert result == """resolved_value->'nested' = '"world"'::jsonb"""


def test_callable_attribute_mapping_validates_path_before_resolving():
    def resolve(name):
        pytest.fail("Invalid paths must not be resolved")

    with pytest.raises(ValueError, match="Invalid path element"):
        build_condition(
            QueryCondition(key="attrib.invalid-key", operator="eq", value="world"),
            column_map={"attrib": resolve},
        )


def test_contains_matches_literal_substring():
    condition = QueryCondition(key="attrib.note", operator="contains", value="15%_it's")
    assert (
        build_condition(condition)
        == "strpos(lower(attrib->>'note'), lower('15%_it''s')) > 0"
    )


def test_boolean_eq_on_native_column():
    true_cond = QueryCondition(key="active", operator="eq", value=True)
    false_cond = QueryCondition(key="active", operator="eq", value=False)
    assert (
        build_condition(true_cond, table_prefix="folders")
        == "coalesce(folders.active, FALSE)"
    )
    assert (
        build_condition(false_cond, table_prefix="folders")
        == "NOT coalesce(folders.active, FALSE)"
    )


def test_boolean_eq_on_attribute_uses_jsonb():
    true_cond = QueryCondition(key="attrib.flag", operator="eq", value=True)
    false_cond = QueryCondition(key="attrib.flag", operator="eq", value=False)
    assert (
        build_condition(true_cond)
        == "coalesce(attrib->'flag', 'false'::jsonb)::boolean"
    )
    assert (
        build_condition(false_cond)
        == "NOT coalesce(attrib->'flag', 'false'::jsonb)::boolean"
    )


def test_boolean_eq_on_single_json_column_uses_jsonb():
    condition = QueryCondition(key="flag", operator="eq", value=True)
    assert (
        build_condition(condition, single_json_column="data")
        == "coalesce(data->'flag', 'false'::jsonb)::boolean"
    )


def test_boolean_eq_on_native_column_in_filter():
    f = QueryFilter(
        conditions=[
            QueryCondition(key="active", operator="eq", value=True),
            QueryCondition(key="attrib.flag", operator="eq", value=False),
        ]
    )
    assert build_filter(f, table_prefix="tasks") == (
        "(coalesce(tasks.active, FALSE)"
        " AND NOT coalesce(tasks.attrib->'flag', 'false'::jsonb)::boolean)"
    )
